'use strict';
const MELATEN_PROMINENT=[
 {name:'Dirk Bach',field:'65',grave:'14',kind:'Ehrengrab',note:'Schauspieler, Moderator und LGBT-Aktivist'},
 {name:'Willy Millowitsch',field:'72',grave:'85',kind:'Denkmal',note:'Volksschauspieler und Theaterleiter'},
 {name:'Johann Maria Farina',field:'60',grave:'Familiengrab',kind:'Kulturdenkmal',note:'Historische Kölner Unternehmerfamilie'},
 {name:'Kriegsgräberstätte',field:'90',grave:'Flur 90 / V1',kind:'Gedenkort',note:'Geschützter Erinnerungsort'}
];
const MELATEN_ENTRANCES=[
 {id:'aachener',label:'Aachener Straße (HWG)',point:[537,833]},
 {id:'pius',label:'Piusstraße',point:[775,453]},
 {id:'weinsberg',label:'Weinsbergstraße',point:[369,141]},
 {id:'oskarl',label:'Oskar-Jäger-Straße',point:[8,534]}
];
let routeTarget='65';
function fieldCapacity(id){const value=Number(state.fields[id]?.capacity||0);return Number.isInteger(value)&&value>0&&value<=500?value:0;}
function numericPlot(g){const matches=[...String(g.number).matchAll(/\d{1,3}/g)];return matches.length?Number(matches.at(-1)[0]):null;}
function plotFor(id,index){return fieldGraves(id).find(g=>numericPlot(g)===index);}
function routePath(start,end){const midY=Math.max(170,Math.min(810,end[1]+(start[1]-end[1])*.45));return `${start[0]},${start[1]} ${start[0]},${midY} ${end[0]},${midY} ${end[0]},${end[1]}`;}
function renderRoute(){const layer=$('#routeLayer');if(!layer)return;const entrance=MELATEN_ENTRANCES.find(e=>e.id===$('#routeEntrance')?.value)||MELATEN_ENTRANCES[0],field=fields.find(f=>f.id===routeTarget);layer.innerHTML=field?`<polyline class="visitor-route" points="${routePath(entrance.point,field.center)}"/><circle class="route-point" cx="${field.center[0]}" cy="${field.center[1]}" r="6"/>`:'';}
function focusRouteTarget(id){if(!ids.has(id))return;routeTarget=id;$('#routeTarget').value=id;select(id);focusField(id);renderRoute();view('karte');}
function renderProminent(){const host=$('#prominentList');if(!host)return;host.innerHTML=MELATEN_PROMINENT.map(p=>`<article class="prominent-card"><div><span class="quality">${esc(p.kind)}</span><h3>${esc(p.name)}</h3><p>Flur ${esc(p.field)} · ${esc(p.grave)}</p><small>${esc(p.note)}</small></div><button class="btn" data-prominent="${esc(p.field)}">Auf Karte zeigen</button></article>`).join('');$$('[data-prominent]').forEach(button=>button.onclick=()=>focusRouteTarget(button.dataset.prominent));}
function renderParcelRaster(id){const capacity=fieldCapacity(id),graves=fieldGraves(id);if(!capacity)return '<p class="micro">Noch keine Flurkapazität hinterlegt. Trage die Anzahl der Grabstellen oben ein, um das Raster zu aktivieren.</p>';const limit=Math.min(capacity,80),cells=[];for(let i=1;i<=limit;i++){const grave=plotFor(id,i),status=grave?grave.status:'Nicht erfasst',cls=grave?(grave.status==='Frei'?'free':grave.status==='Belegt'?'occupied':grave.status==='Reserviert'?'reserved':grave.status==='Aufgelöst'?'closed':'unknown'):'unrecorded';cells.push(`<button class="plot-cell ${cls} ${grave&&DFM.deadline(grave)==='expired'?'expired':''} ${grave&&['Denkmal','Ehrengrab','Kriegsgrab'].includes(grave.heritage)?'heritage':''}" data-plot="${i}" ${grave?`data-grave-id="${esc(grave.id)}"`:''} title="Grabstelle ${i}: ${esc(status)}">${i}</button>`);}return `<div class="parcel-summary"><strong>${graves.length}</strong> erfasst <span>${Math.max(0,capacity-graves.length)} noch nicht erfasst</span></div><div class="plot-grid">${cells.join('')}</div>${capacity>limit?`<p class="micro">Die ersten ${limit} von ${capacity} Grabstellen werden dargestellt.</p>`:''}<div class="plot-legend"><span class="occupied">Belegt</span><span class="free">Frei</span><span class="reserved">Reserviert</span><span class="unrecorded">Nicht erfasst</span></div>`;}
const enterpriseDetail=renderDetail;
renderDetail=function(){enterpriseDetail();const fieldState=state.fields[selected]||{},form=$('#fieldForm'),settings=document.createElement('div');settings.className='field-settings';settings.innerHTML=`<label class="formlabel">Grabstellen laut Bestand<input name="capacity" type="number" min="0" max="500" step="1" value="${fieldCapacity(selected)||''}" placeholder="z. B. 80"></label><label class="formlabel">Flurtyp<input name="burialType" maxlength="120" value="${esc(fieldState.burialType||'')}" placeholder="z. B. Allgemeine Grabflur"></label>`;form.querySelector('button[type="submit"]').before(settings);form.onsubmit=e=>{e.preventDefault();const data=new FormData(form),capacity=Number(data.get('capacity')||0);if(!Number.isInteger(capacity)||capacity<0||capacity>500)return toast('Bitte eine Kapazität zwischen 0 und 500 eingeben.');change(s=>s.fields[selected]={...s.fields[selected],condition:data.get('condition'),notes:data.get('notes'),capacity,burialType:String(data.get('burialType')||'').trim()},'Flurdaten gespeichert.');};$('#fieldNewTask').textContent='+ Arbeitsauftrag für diese Fläche';const section=document.createElement('section');section.className='plot-overview';section.innerHTML=`<div class="sectionmini"><div><h3>Einzelgrab-Raster</h3><span>Parzellenstatus · klickbar</span></div></div>${renderParcelRaster(selected)}<button class="btn primary interment-field">+ Beisetzung in Flur ${esc(selected)} erfassen</button>`;$('#detail .detailbody').append(section);$$('.plot-cell').forEach(cell=>cell.onclick=()=>{if(cell.dataset.graveId)return graveDialog(cell.dataset.graveId);graveDialog();$('#graveForm [name="number"]').value=cell.dataset.plot;$('#graveForm [name="status"]').value='Frei';});$('.interment-field').onclick=()=>{graveDialog();$('#modalTitle').textContent='Beisetzung in Flur '+selected;$('#graveForm [name="status"]').value='Belegt';$('#graveForm [name="burial"]').focus();};};
const enterpriseRender=render;
render=function(){enterpriseRender();renderProminent();renderRoute();};
function setupEnterprise(){const routeCard=document.createElement('section');routeCard.className='route-card';routeCard.innerHTML=`<div class="gis-reference"><strong>Melaten-GIS Referenz</strong><span>50° 56′ 10″ N, 6° 55′ 11″ O · ca. 43,5 ha</span></div><h3>Besucher-Wegefinder</h3><label>Eingang<select id="routeEntrance">${MELATEN_ENTRANCES.map(e=>`<option value="${e.id}">${e.label}</option>`).join('')}</select></label><label>Ziel<select id="routeTarget">${MELATEN_PROMINENT.map(p=>`<option value="${p.field}">${p.name} · Flur ${p.field}</option>`).join('')}</select></label><button id="calculateRoute" class="btn primary">Route anzeigen</button><button id="clearRoute" class="linkbutton">Route löschen</button><p>Schematische Orientierung, keine barrierefreie Navigation.</p>`;$('.mapcard').prepend(routeCard);$('#calculateRoute').onclick=()=>focusRouteTarget($('#routeTarget').value);$('#clearRoute').onclick=()=>{$('#routeLayer').innerHTML='';};$('#routeEntrance').onchange=renderRoute;$('#routeTarget').onchange=e=>routeTarget=e.target.value;$('#headerInterment').onclick=()=>{$('#newInterment').click();};render();}
setupEnterprise();
